// Deliberately minimal existing behavior, not an implementation of SPEC.md.
export function normalizeLevel(value, unit) {
  if (unit === 'mm' && Number.isInteger(value)) return value;
  if (unit === 'cm' && Number.isInteger(value * 10)) return value * 10;
  throw new TypeError('invalid level');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeLevel } from './service.mjs';
test('existing level conversion only, not reservoir qualification', () => {
  assert.equal(normalizeLevel(125, 'cm'), 1250);
  assert.equal(normalizeLevel(1250, 'mm'), 1250);
  assert.throws(() => normalizeLevel(125, 'metres'), TypeError);
});

{
  "private": true,
  "type": "module",
  "scripts": { "test": "node --test" }
}

